local CoreWashingDipMaker = {}
local PRODUCTS = {
    iron_corewashingdip = { name = "Železni kopel za pranje jedrc", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni kopel za pranje jedrc za livarje." },
    bronze_corewashingdip = { name = "Bronast kopel za pranje jedrc", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast kopel za pranje jedrc za livarje." },
    silver_corewashingdip = { name = "Srebrn kopel za pranje jedrc", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn kopel za pranje jedrc za livarje." },
    gilded_corewashingdip = { name = "Pozlačen kopel za pranje jedrc", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen kopel za pranje jedrc za livarje." },
    jewel_set_corewashingdip = { name = "Draguljast kopel za pranje jedrc", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast kopel za pranje jedrc za livarje." },
    royal_sovereign_corewashingdip = { name = "Kraljevski suveren kopel za pranje jedrc", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren kopel za pranje jedrc z biseri za krono." },
}
local BUILDINGS = {
    corewashingdip_workshop = { name = "Corewashingdip delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    corewashingdip_house = { name = "Corewashingdip hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_corewashingdip_atelier = { name = "Mojstrski corewashingdip atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_corewashingdip_palace = { name = "Suverena corewashingdip palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
CoreWashingDipMaker.ironStock=12; CoreWashingDipMaker.bronzeStock=10; CoreWashingDipMaker.woodStock=14; CoreWashingDipMaker.leatherStock=12; CoreWashingDipMaker.silverStock=8; CoreWashingDipMaker.goldStock=6; CoreWashingDipMaker.jewelStock=4; CoreWashingDipMaker.pearlStock=4
CoreWashingDipMaker.productStock = {}; CoreWashingDipMaker.buildings = {}; CoreWashingDipMaker.maker = nil; CoreWashingDipMaker.activeMaking = {}; CoreWashingDipMaker.totalProducts = 0; CoreWashingDipMaker.dayTimer = 0
function CoreWashingDipMaker.init() CoreWashingDipMaker.ironStock=12; CoreWashingDipMaker.bronzeStock=10; CoreWashingDipMaker.woodStock=14; CoreWashingDipMaker.leatherStock=12; CoreWashingDipMaker.silverStock=8; CoreWashingDipMaker.goldStock=6; CoreWashingDipMaker.jewelStock=4; CoreWashingDipMaker.pearlStock=4; CoreWashingDipMaker.productStock={}; CoreWashingDipMaker.buildings={}; CoreWashingDipMaker.maker=nil; CoreWashingDipMaker.activeMaking={}; CoreWashingDipMaker.totalProducts=0; CoreWashingDipMaker.dayTimer=0; print("[CoreWashingDipMaker] Royal Core Washing Dip Maker System initialized (6 products, 4 buildings)") end
function CoreWashingDipMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CoreWashingDipMaker.maker={name=n or ("Kopelnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kopelnik najet: %s (spretnost: %d)",CoreWashingDipMaker.maker.name,s),"success") end; return true end
function CoreWashingDipMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CoreWashingDipMaker.build(id) local ok,e=CoreWashingDipMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CoreWashingDipMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CoreWashingDipMaker.getQualityBonus() local b=0; for _,bd in ipairs(CoreWashingDipMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CoreWashingDipMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CoreWashingDipMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CoreWashingDipMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and CoreWashingDipMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and CoreWashingDipMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and CoreWashingDipMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CoreWashingDipMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CoreWashingDipMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CoreWashingDipMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CoreWashingDipMaker.buildings==0 then return false,"Potrebna kopelna delavnica" end; if not CoreWashingDipMaker.maker then return false,"Potreben kopelnik" end; return true end
function CoreWashingDipMaker.make(pt,qty) qty=qty or 1; local ok,e=CoreWashingDipMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CoreWashingDipMaker.ironStock=CoreWashingDipMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then CoreWashingDipMaker.bronzeStock=CoreWashingDipMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then CoreWashingDipMaker.woodStock=CoreWashingDipMaker.woodStock-d.woodCost*qty end; if d.leatherCost then CoreWashingDipMaker.leatherStock=CoreWashingDipMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then CoreWashingDipMaker.silverStock=CoreWashingDipMaker.silverStock-d.silverCost*qty end; if d.goldCost then CoreWashingDipMaker.goldStock=CoreWashingDipMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CoreWashingDipMaker.jewelStock=CoreWashingDipMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CoreWashingDipMaker.pearlStock=CoreWashingDipMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CoreWashingDipMaker.maker then t=math.max(1,t-math.floor(CoreWashingDipMaker.maker.skill/13)) end; table.insert(CoreWashingDipMaker.activeMaking,{id="corewashingdip_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CoreWashingDipMaker.completeMaking(m) local q=1.0+(CoreWashingDipMaker.getQualityBonus()/100); if CoreWashingDipMaker.maker then q=q+(CoreWashingDipMaker.maker.skill/140) end; q=math.min(2.5,q); CoreWashingDipMaker.productStock[m.productType]=(CoreWashingDipMaker.productStock[m.productType] or 0)+m.quantity; CoreWashingDipMaker.totalProducts=CoreWashingDipMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CoreWashingDipMaker.maker then CoreWashingDipMaker.maker.itemsMade=CoreWashingDipMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CoreWashingDipMaker.maker.skill=math.min(100,CoreWashingDipMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kopel izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"corewashingdip.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CoreWashingDipMaker.update(dt) if not _G.state then return end; CoreWashingDipMaker.dayTimer=CoreWashingDipMaker.dayTimer+dt; if CoreWashingDipMaker.dayTimer>=30 then CoreWashingDipMaker.dayTimer=0; for i=#CoreWashingDipMaker.activeMaking,1,-1 do local m=CoreWashingDipMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CoreWashingDipMaker.completeMaking(m); table.remove(CoreWashingDipMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CoreWashingDipMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CoreWashingDipMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CoreWashingDipMaker.getStats() return {ironStock=CoreWashingDipMaker.ironStock,bronzeStock=CoreWashingDipMaker.bronzeStock,woodStock=CoreWashingDipMaker.woodStock,leatherStock=CoreWashingDipMaker.leatherStock,silverStock=CoreWashingDipMaker.silverStock,goldStock=CoreWashingDipMaker.goldStock,jewelStock=CoreWashingDipMaker.jewelStock,pearlStock=CoreWashingDipMaker.pearlStock,productStock=CoreWashingDipMaker.productStock,numBuildings=#CoreWashingDipMaker.buildings,hasMaker=CoreWashingDipMaker.maker~=nil,makerName=CoreWashingDipMaker.maker and CoreWashingDipMaker.maker.name or "—",makerSkill=CoreWashingDipMaker.maker and CoreWashingDipMaker.maker.skill or 0,activeMaking=#CoreWashingDipMaker.activeMaking,totalProducts=CoreWashingDipMaker.totalProducts} end
return CoreWashingDipMaker
